<?php
require_once __DIR__ . '/../../includes/auth-check.php';
require_once __DIR__ . '/../../includes/admin-ui.php';
require_once __DIR__ . '/../../includes/analytics.php';
require_once __DIR__ . '/../../includes/cache.php';
admin_require_permission($pdo,$admin,'manage_wordbank');
$wordbankMetadataReady=false;
try{$pdo->query('SELECT category_id,partner_length,verification_status,source FROM wordbank_terms LIMIT 1');$wordbankMetadataReady=true;}catch(Throwable $error){error_log('Wordbank verification metadata migration not applied: '.$error->getMessage());}
$errorMessage='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();$action=request_string($_POST, 'action', '');
 try{
  if($action==='review_setting'){
   save_setting($pdo,'generator_review_only',isset($_POST['generator_review_only']),(int)$admin['id'],true);
   audit_log($pdo,(int)$admin['id'],'wordbank.review_filter_updated','generator','review-only');cache_clear_all();flash('success','English review filter updated.');redirect_to('admin/domain-brain');
  }
  if($action==='term_delete'){
   $id=filter_var($_POST['id']??null,FILTER_VALIDATE_INT);if(!$id)throw new RuntimeException('Invalid vocabulary entry.');
   $pdo->prepare('DELETE FROM wordbank_terms WHERE id=:id')->execute(['id'=>$id]);audit_log($pdo,(int)$admin['id'],'wordbank.term_deleted','wordbank_term',(string)$id);cache_clear_all();flash('success','Word removed.');redirect_to('admin/domain-brain');
  }
  if($action==='term_save'){
   $id=filter_var($_POST['id']??null,FILTER_VALIDATE_INT)?:0;
   $word=strtolower(trim(substr(request_string($_POST, 'word', ''),0,48)));
   $type=in_array(($_POST['term_type']??''),['curated','brandable','long_partner'],true)?(string)$_POST['term_type']:'curated';
   $reviewed=isset($_POST['english_reviewed'])?1:0;$active=isset($_POST['is_active'])?1:0;$note=trim(substr(strip_tags(request_string($_POST, 'note', '')),0,255));
   $categoryId=filter_var($_POST['category_id']??null,FILTER_VALIDATE_INT);$categoryId=($categoryId!==false&&$categoryId>0)?(int)$categoryId:null;
   $partnerLength=filter_var($_POST['partner_length']??null,FILTER_VALIDATE_INT);$partnerLength=($partnerLength!==false&&$partnerLength>=2&&$partnerLength<=6)?(int)$partnerLength:null;
   if(!preg_match('/^[a-z0-9-]{2,48}$/',$word))throw new RuntimeException('A word must contain 2–48 lowercase English letters, numbers or hyphens.');
   if($type==='long_partner'&&strlen($word)<7)throw new RuntimeException('A long-partner word must contain at least 7 characters.');
   if($partnerLength!==null&&strlen($word)!==$partnerLength)throw new RuntimeException('The 2L–6L length category must match the partner word.');
   if($categoryId!==null&&$wordbankMetadataReady){$categoryCheck=$pdo->prepare('SELECT id FROM wordbank_categories WHERE id=:id');$categoryCheck->execute(['id'=>$categoryId]);if(!$categoryCheck->fetchColumn())throw new RuntimeException('Choose an existing Domain Brain category.');}
   $verificationStatus=$reviewed?'reviewed':'unverified';
   if($id){
    if($wordbankMetadataReady){$save=$pdo->prepare('UPDATE wordbank_terms SET word=:word,term_type=:type,english_reviewed=:reviewed,category_id=:category,partner_length=:length,verification_status=:verification,is_active=:active,note=:note,updated_by=:admin WHERE id=:id');$save->execute(['word'=>$word,'type'=>$type,'reviewed'=>$reviewed,'category'=>$categoryId,'length'=>$partnerLength,'verification'=>$verificationStatus,'active'=>$active,'note'=>$note,'admin'=>(int)$admin['id'],'id'=>$id]);}
    else{$save=$pdo->prepare('UPDATE wordbank_terms SET word=:word,term_type=:type,english_reviewed=:reviewed,is_active=:active,note=:note,updated_by=:admin WHERE id=:id');$save->execute(['word'=>$word,'type'=>$type,'reviewed'=>$reviewed,'active'=>$active,'note'=>$note,'admin'=>(int)$admin['id'],'id'=>$id]);}
   }else{
    if($wordbankMetadataReady){$save=$pdo->prepare('INSERT INTO wordbank_terms(word,term_type,english_reviewed,category_id,partner_length,verification_status,source,is_active,note,created_by,updated_by) VALUES(:word,:type,:reviewed,:category,:length,:verification,:source,:active,:note,:created,:updated)');$save->execute(['word'=>$word,'type'=>$type,'reviewed'=>$reviewed,'category'=>$categoryId,'length'=>$partnerLength,'verification'=>$verificationStatus,'source'=>'manual','active'=>$active,'note'=>$note,'created'=>(int)$admin['id'],'updated'=>(int)$admin['id']]);}
    else{$save=$pdo->prepare('INSERT INTO wordbank_terms(word,term_type,english_reviewed,is_active,note,created_by,updated_by) VALUES(:word,:type,:reviewed,:active,:note,:created,:updated)');$save->execute(['word'=>$word,'type'=>$type,'reviewed'=>$reviewed,'active'=>$active,'note'=>$note,'created'=>(int)$admin['id'],'updated'=>(int)$admin['id']]);}
    $id=(int)$pdo->lastInsertId();
   }
   audit_log($pdo,(int)$admin['id'],'wordbank.term_saved','wordbank_term',(string)$id,$word.' · '.$type.' · '.$verificationStatus);cache_clear_all();flash('success','Vocabulary entry saved.');redirect_to('admin/domain-brain');
  }
  if($action==='category_delete'){
   $id=filter_var($_POST['id']??null,FILTER_VALIDATE_INT);
   if(!$id)throw new RuntimeException('Invalid category.');
   $check=$pdo->prepare('SELECT category_key FROM wordbank_categories WHERE id=:id LIMIT 1');$check->execute(['id'=>$id]);$categoryKey=(string)$check->fetchColumn();
   if($categoryKey===''||$categoryKey==='smart')throw new RuntimeException('The built-in general category cannot be deleted.');
   $pdo->prepare('DELETE FROM wordbank_categories WHERE id=:id')->execute(['id'=>$id]);audit_log($pdo,(int)$admin['id'],'wordbank.category_deleted','wordbank_category',$categoryKey);cache_clear_all();flash('success','Category deleted.');redirect_to('admin/domain-brain');
  }
  if($action==='category_save'){
   $id=filter_var($_POST['id']??null,FILTER_VALIDATE_INT)?:0;
   $key=strtolower(trim(substr(request_string($_POST, 'category_key', ''),0,60)));
   $label=trim(substr(strip_tags(request_string($_POST, 'label', '')),0,120));$description=trim(substr(strip_tags(request_string($_POST, 'description', '')),0,255));
   $keywords=trim(request_string($_POST, 'detection_keywords', ''));$preferred=trim(request_string($_POST, 'preferred_words', ''));$order=max(-10000,min(10000,(int)($_POST['display_order']??0)));$active=isset($_POST['is_active'])?1:0;
   if(!preg_match('/^[a-z][a-z0-9_]{1,59}$/',$key)||$label==='')throw new RuntimeException('Use a unique category key (lowercase letters, numbers, underscores) and a label.');
   $parseList=static function(string $value):array{$items=preg_split('/[\r\n,]+/',$value)?:[];$clean=[];foreach($items as $item){$item=strtolower(trim($item));if($item==='')continue;if(strlen($item)>48||!preg_match('/^[a-z0-9-]+$/',$item))throw new RuntimeException('Category keywords and preferred words must be single alphanumeric words.');$clean[]=$item;}return array_values(array_unique(array_slice($clean,0,150)));};
   $keywordsJson=json_encode($parseList($keywords),JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR);$preferredJson=json_encode($parseList($preferred),JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR);
   if($id){$existing=$pdo->prepare('SELECT category_key FROM wordbank_categories WHERE id=:id');$existing->execute(['id'=>$id]);$oldKey=$existing->fetchColumn();if(!$oldKey)throw new RuntimeException('Category not found.');if($oldKey==='smart'&&$key!=='smart')throw new RuntimeException('The built-in general category key cannot be changed.');$save=$pdo->prepare('UPDATE wordbank_categories SET category_key=:key,label=:label,description=:description,detection_keywords_json=:keywords,preferred_words_json=:preferred,display_order=:sort,is_active=:active,updated_by=:admin WHERE id=:id');$save->execute(['key'=>$key,'label'=>$label,'description'=>$description,'keywords'=>$keywordsJson,'preferred'=>$preferredJson,'sort'=>$order,'active'=>$active,'admin'=>(int)$admin['id'],'id'=>$id]);}
   else{$save=$pdo->prepare('INSERT INTO wordbank_categories(category_key,label,description,detection_keywords_json,preferred_words_json,display_order,is_active,updated_by) VALUES(:key,:label,:description,:keywords,:preferred,:sort,:active,:admin)');$save->execute(['key'=>$key,'label'=>$label,'description'=>$description,'keywords'=>$keywordsJson,'preferred'=>$preferredJson,'sort'=>$order,'active'=>$active,'admin'=>(int)$admin['id']]);$id=(int)$pdo->lastInsertId();}
   audit_log($pdo,(int)$admin['id'],'wordbank.category_saved','wordbank_category',$key,$label);cache_clear_all();flash('success','Category saved.');redirect_to('admin/domain-brain');
  }
 }catch(Throwable $error){if($pdo->inTransaction())$pdo->rollBack();error_log('Domain brain save: '.$error->getMessage());$errorMessage=$error instanceof RuntimeException?$error->getMessage():'Could not save the vocabulary or category. Check for duplicate words or keys.';}
}
$search=trim(substr(request_string($_GET, 'q', ''),0,48));
$typeFilter=in_array(($_GET['type']??''),['curated','brandable','long_partner'],true)?(string)$_GET['type']:'';
$where='1=1';$params=[];
if($search!==''){$where.=' AND t.word LIKE :q';$params['q']='%'.$search.'%';}
if($typeFilter!==''){$where.=' AND t.term_type=:type';$params['type']=$typeFilter;}
if($wordbankMetadataReady){
 $termsSql="SELECT t.id,t.word,t.term_type,t.english_reviewed,t.is_active,t.note,t.updated_at,t.category_id,t.partner_length,t.verification_status,t.source,c.label AS category_label FROM wordbank_terms t LEFT JOIN wordbank_categories c ON c.id=t.category_id WHERE $where ORDER BY t.term_type,t.word LIMIT 300";
}else{
 $termsSql="SELECT t.id,t.word,t.term_type,t.english_reviewed,t.is_active,t.note,t.updated_at FROM wordbank_terms t WHERE $where ORDER BY t.term_type,t.word LIMIT 300";
}
$termsQuery=$pdo->prepare($termsSql);$termsQuery->execute($params);$terms=$termsQuery->fetchAll();
$termEdit=null;if(isset($_GET['edit_term'])){$get=$pdo->prepare('SELECT * FROM wordbank_terms WHERE id=:id');$get->execute(['id'=>filter_var($_GET['edit_term'],FILTER_VALIDATE_INT)]);$termEdit=$get->fetch()?:null;}
$categories=$pdo->query('SELECT * FROM wordbank_categories ORDER BY display_order,label')->fetchAll();$categoryEdit=null;if(isset($_GET['edit_category'])){$get=$pdo->prepare('SELECT * FROM wordbank_categories WHERE id=:id');$get->execute(['id'=>filter_var($_GET['edit_category'],FILTER_VALIDATE_INT)]);$categoryEdit=$get->fetch()?:null;}
$reviewOnly=(bool)setting($pdo,'generator_review_only',false);$counts=$pdo->query('SELECT term_type,COUNT(*) AS total,SUM(is_active=1) AS active,SUM(english_reviewed=1) AS reviewed FROM wordbank_terms GROUP BY term_type')->fetchAll();
admin_header($pdo,$admin,'Domain brain');
?>
<?php if($errorMessage!==''): ?><div class="notice notice-error" role="alert"><?=e($errorMessage)?></div><?php endif; ?>
<?php if(!$wordbankMetadataReady): ?><div class="notice notice-warning" role="status">2L–6L category and verification metadata needs the enterprise migration. Existing vocabulary management remains available. Run <code>php scripts/migrate-enterprise-cms.php</code> from the CMS directory.</div><?php endif; ?>
<section class="admin-card"><p class="admin-card-eyebrow">Generator controls</p><h2>Vocabulary controls</h2><div class="admin-stats"><?php foreach($counts as $count): ?><article class="admin-stat"><span><?=e(str_replace('_',' ',ucfirst($count['term_type'])))?></span><strong><?=number_format((int)$count['active'])?></strong><small><?=number_format((int)$count['reviewed'])?> marked as human-reviewed</small></article><?php endforeach; ?></div><form method="post" class="admin-form"><?=csrf_field()?><input type="hidden" name="action" value="review_setting"><label class="inline-check"><input type="checkbox" name="generator_review_only" value="1" <?=$reviewOnly?'checked':''?>><span>In strict mode, use only terms explicitly marked as human-reviewed, including long partner words.</span></label><p>Off by default to preserve the supplied curated list. This flag is an editorial state, not dictionary, legal or trademark certification.</p><button class="button button-small" type="submit">Save review filter</button></form></section>
<?php if($wordbankMetadataReady): ?>
<section class="admin-card gemini-wordbank" data-gemini-generator data-endpoint="<?=e(app_url('api/admin-domain-brain-gemini'))?>" data-csrf="<?=e(csrf_token())?>">
  <p class="admin-card-eyebrow">AI-assisted workflow</p><h2>Gemini wordbank generation</h2>
