  <div class="form-row"><div class="field"><label for="gemini-category">Category destination</label><select id="gemini-category" data-gemini-category><option value="create">Create or reuse a category from this niche</option><?php foreach($categories as $categoryOption): ?><option value="<?= (int)$categoryOption['id'] ?>" <?= empty($categoryOption['is_active'])?'disabled':'' ?>><?=e($categoryOption['label'])?><?=empty($categoryOption['is_active'])?' (inactive)':''?> · <?=e($categoryOption['category_key'])?></option><?php endforeach; ?></select></div><div class="field gemini-actions"><span class="form-help">The insert action adds rows to <code>wordbank_terms</code> and does not publish content.</span><button class="button button-primary" type="button" data-gemini-generate>Generate preview</button></div></div>
  <p class="dialog-message" data-gemini-status role="status" aria-live="polite"></p>
  <div data-gemini-preview hidden>
    <div class="gemini-preview-heading"><h3>Preview <span data-gemini-count>0</span> suggestions</h3><label class="inline-check"><input type="checkbox" data-gemini-select-all checked><span>Select all valid rows</span></label></div>
    <div class="admin-table-wrap"><table class="admin-table gemini-preview-table"><thead><tr><th>Select</th><th>Term</th><th>Length</th><th>Model hint</th><th>Model self-report / note</th></tr></thead><tbody data-gemini-rows></tbody></table></div>
    <div class="admin-actions gemini-insert-actions"><button class="button button-primary" type="button" data-gemini-insert disabled>Insert selected as unverified</button><span class="form-help" data-gemini-selected-count>0 selected</span></div>
  </div>
</section>
<?php endif; ?>
<div class="admin-columns">
  <section class="admin-card"><p class="admin-card-eyebrow">Vocabulary entry</p><h2><?= $termEdit?'Edit':'Add' ?> term</h2><form class="admin-form" method="post"><?=csrf_field()?><?php if($termEdit): ?><input type="hidden" name="id" value="<?=(int)$termEdit['id']?>"><?php endif; ?><input type="hidden" name="action" value="term_save">
    <div class="form-row"><div class="field"><label for="word">Word or component</label><input id="word" name="word" maxlength="48" pattern="[a-zA-Z0-9-]{2,48}" required value="<?=e($termEdit['word']??'')?>"></div><div class="field"><label for="term_type">Word-list type</label><select id="term_type" name="term_type"><?php foreach(['curated'=>'Curated (strict list)','brandable'=>'Brandable (creative)','long_partner'=>'Long partner (7+)'] as $typeKey=>$typeLabel): ?><option value="<?=e($typeKey)?>" <?=($termEdit['term_type']??'curated')===$typeKey?'selected':''?>><?=e($typeLabel)?></option><?php endforeach; ?></select></div></div>
    <?php if($wordbankMetadataReady): ?><div class="form-row"><div class="field"><label for="term_category">Domain Brain category</label><select id="term_category" name="category_id"><option value="">No category</option><?php foreach($categories as $categoryOption): ?><option value="<?=(int)$categoryOption['id']?>" <?=(int)($termEdit['category_id']??0)===(int)$categoryOption['id']?'selected':''?>><?=e($categoryOption['label'])?></option><?php endforeach; ?></select></div><div class="field"><label for="partner_length">Partner length category</label><select id="partner_length" name="partner_length"><option value="">Not assigned</option><?php for($length=2;$length<=6;$length++): ?><option value="<?=$length?>" <?=(int)($termEdit['partner_length']??0)===$length?'selected':''?>><?=$length?>L partner</option><?php endfor; ?></select></div></div><?php endif; ?>
    <div class="field"><label for="note">Editorial note</label><input id="note" name="note" maxlength="255" value="<?=e($termEdit['note']??'')?>"></div>
    <?php if($wordbankMetadataReady&&$termEdit): ?><p class="form-help">Source: <strong><?=e(ucfirst((string)($termEdit['source']??'manual')))?></strong> · Verification: <strong><?=e((string)($termEdit['verification_status']??'unverified'))?></strong></p><?php endif; ?>
    <label class="inline-check"><input type="checkbox" name="english_reviewed" value="1" <?=($termEdit&&$termEdit['english_reviewed'])?'checked':''?>><span>Mark as human-reviewed English vocabulary</span></label><label class="inline-check"><input type="checkbox" name="is_active" value="1" <?=!$termEdit||$termEdit['is_active']?'checked':''?>><span>Include in generator</span></label>
    <div class="admin-actions"><button class="button button-primary" type="submit">Save term</button><?php if($termEdit): ?><a href="<?=e(app_url('admin/domain-brain'))?>">Cancel</a><?php endif; ?></div>
  </form></section>
  <section class="admin-card"><p class="admin-card-eyebrow">Taxonomy</p><h2><?= $categoryEdit?'Edit':'Add' ?> category</h2><form class="admin-form" method="post"><?=csrf_field()?><?php if($categoryEdit): ?><input type="hidden" name="id" value="<?=(int)$categoryEdit['id']?>"><?php endif; ?><input type="hidden" name="action" value="category_save"><div class="form-row"><div class="field"><label for="category_key">Category key</label><input id="category_key" name="category_key" maxlength="60" pattern="[a-z][a-z0-9_]{1,59}" required value="<?=e($categoryEdit['category_key']??'')?>" <?=($categoryEdit['category_key']??'')==='smart'?'readonly':''?>></div><div class="field"><label for="category_label">Display label</label><input id="category_label" name="label" maxlength="120" required value="<?=e($categoryEdit['label']??'')?>"></div></div><div class="field"><label for="description">Description</label><input id="description" name="description" maxlength="255" value="<?=e($categoryEdit['description']??'')?>"></div><div class="field"><label for="detection_keywords">Auto-detection keywords (comma or newline separated)</label><textarea id="detection_keywords" name="detection_keywords" rows="4"><?=e(implode("\n",json_decode((string)($categoryEdit['detection_keywords_json']??'[]'),true)?:[]))?></textarea></div><div class="field"><label for="preferred_words">Preferred generator partners (comma or newline separated)</label><textarea id="preferred_words" name="preferred_words" rows="4"><?=e(implode("\n",json_decode((string)($categoryEdit['preferred_words_json']??'[]'),true)?:[]))?></textarea></div><div class="form-row"><div class="field"><label for="display_order">Display order</label><input id="display_order" name="display_order" type="number" min="-10000" max="10000" value="<?=e($categoryEdit['display_order']??10)?>"></div><label class="inline-check"><input type="checkbox" name="is_active" value="1" <?=!$categoryEdit||$categoryEdit['is_active']?'checked':''?>><span>Show category in generator</span></label></div><div class="admin-actions"><button class="button button-primary" type="submit">Save category</button><?php if($categoryEdit): ?><a href="<?=e(app_url('admin/domain-brain'))?>">Cancel</a><?php endif; ?></div></form></section>
</div>
<section class="admin-card"><p class="admin-card-eyebrow">Wordbank</p><h2>Vocabulary terms (latest 300 matching)</h2><form class="admin-filter" method="get"><input name="q" type="search" value="<?=e($search)?>" placeholder="Find a term"><select name="type"><option value="">All word types</option><?php foreach(['curated','brandable','long_partner'] as $option): ?><option value="<?=e($option)?>" <?=$typeFilter===$option?'selected':''?>><?=e(ucfirst(str_replace('_',' ',$option)))?></option><?php endforeach; ?></select><button class="button button-small" type="submit">Filter</button></form><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Word &amp; length</th><th>Type / verification</th><?php if($wordbankMetadataReady): ?><th>Category / source</th><?php endif; ?><th>State</th><th>Actions</th></tr></thead><tbody><?php foreach($terms as $term): ?><tr><td><strong><?=e($term['word'])?></strong><?php if($wordbankMetadataReady): ?><br><span class="admin-badge"><?=!empty($term['partner_length'])?(int)$term['partner_length'].'L partner':'Length not assigned'?></span><?php endif; ?><?php if($term['note']): ?><br><small><?=e($term['note'])?></small><?php endif; ?></td><td><?=e(ucfirst(str_replace('_',' ',$term['term_type'])))?><br><span class="admin-badge"><?=$term['english_reviewed']?'Human-reviewed':'Unverified'?></span><?php if($wordbankMetadataReady): ?><br><small><?=e($term['verification_status'])?></small><?php endif; ?></td><?php if($wordbankMetadataReady): ?><td><?=e($term['category_label']?:'—')?><br><small>Source: <?=e($term['source'])?></small></td><?php endif; ?><td><?=$term['is_active']?'Active':'Inactive'?></td><td><div class="admin-actions"><a href="<?=e(app_url('admin/domain-brain?edit_term='.(int)$term['id']))?>">Edit</a><form method="post" data-confirm="Remove this term from the word bank?"><?=csrf_field()?><input type="hidden" name="action" value="term_delete"><input type="hidden" name="id" value="<?=(int)$term['id']?>"><button class="admin-danger" type="submit">Delete</button></form></div></td></tr><?php endforeach; ?><?php if(!$terms): ?><tr><td colspan="<?= $wordbankMetadataReady?5:4 ?>">No terms found.</td></tr><?php endif; ?></tbody></table></div></section>
<section class="admin-card"><p class="admin-card-eyebrow">Taxonomy</p><h2>Industry categories</h2><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Category</th><th>Keywords / preferred words</th><th>Order</th><th>Actions</th></tr></thead><tbody><?php foreach($categories as $category): ?><tr><td><strong><?=e($category['label'])?></strong><br><code><?=e($category['category_key'])?></code><br><small><?=e($category['description'])?></small></td><td><?=number_format(count(json_decode((string)$category['detection_keywords_json'],true)?:[]))?> detection keywords<br><?=number_format(count(json_decode((string)$category['preferred_words_json'],true)?:[]))?> preferred words</td><td><?=(int)$category['display_order']?></td><td><div class="admin-actions"><a href="<?=e(app_url('admin/domain-brain?edit_category='.(int)$category['id']))?>">Edit</a><?php if($category['category_key']!=='smart'): ?><form method="post" data-confirm="Delete this category? Terms remain in the word bank."><?=csrf_field()?><input type="hidden" name="action" value="category_delete"><input type="hidden" name="id" value="<?=(int)$category['id']?>"><button class="admin-danger" type="submit">Delete</button></form><?php endif; ?></div></td></tr><?php endforeach; ?></tbody></table></div></section>
<script src="<?=e(asset_url('js/admin-tools.js'))?>" defer></script>
<?php admin_footer(); ?>
